import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Rate Limiting","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/ratelimit.md","filePath":"advanced/ratelimit.md","lastUpdated":1784888953000}'),n={name:"advanced/ratelimit.md"};function o(r,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>swag2mcp has a built-in rate limiter that prevents the LLM from calling the same API endpoint too frequently. This protects against accidental duplicate calls and respects API rate limits.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Each endpoint has a cooldown period. If the LLM tries to call the same endpoint again within the cooldown, the call is rejected with a structured error.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → executes</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → rejected with rate_limit error</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → executes (cooldown has passed)</span></span></code></pre></div><h3 id="default-behavior" tabindex="-1">Default behavior <a class="header-anchor" href="#default-behavior" aria-label="Permalink to &quot;Default behavior&quot;">​</a></h3><ul><li><strong>Cooldown:</strong> 10 seconds per endpoint</li><li><strong>Scope:</strong> Per-endpoint — calling endpoint A does not affect endpoint B</li><li><strong>Error response:</strong> The LLM receives an <code>LLMError</code> with code <code>rate_limit</code> and a message indicating how long to wait</li><li><strong>Reset:</strong> After 10 seconds of inactivity on that endpoint</li></ul><h3 id="error-format" tabindex="-1">Error format <a class="header-anchor" href="#error-format" aria-label="Permalink to &quot;Error format&quot;">​</a></h3><p>When rate limited, the LLM receives:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate limit exceeded for endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: try again in 8 seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wait for the cooldown period to expire, then try invoking the endpoint again. Use the search tool to find other endpoints you can call in the meantime.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The LLM can use this information to wait and retry, or switch to a different endpoint.</p><h3 id="why-it-exists" tabindex="-1">Why it exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to &quot;Why it exists&quot;">​</a></h3><ul><li><strong>Prevents accidental duplicate calls</strong> — the LLM might call the same endpoint multiple times in quick succession</li><li><strong>Protects against API rate limits</strong> — many APIs have their own rate limits, and hitting them would cause errors</li><li><strong>Saves resources</strong> — reduces unnecessary network traffic</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>You can disable the rate limiter or change the cooldown interval:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable the rate limiter entirely</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Custom cooldown interval</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>Type:</strong> <code>bool</code></li><li><strong>Default:</strong> <code>false</code></li><li><strong>Effect:</strong> When <code>true</code>, the per-endpoint rate limiter is disabled. The LLM can call the same endpoint repeatedly without waiting.</li><li><strong>When to enable:</strong> Testing, debugging, or when you need to call the same endpoint multiple times in quick succession.</li><li><strong>When to keep disabled (recommended):</strong> Production. The rate limiter prevents accidental abuse.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>Type:</strong> duration (Go format: <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>Default:</strong> <code>10s</code></li><li><strong>Effect:</strong> Sets the cooldown period between calls to the same endpoint.</li><li><strong>When to increase:</strong> APIs with strict rate limits (e.g., 10 requests per minute).</li><li><strong>When to decrease:</strong> Internal APIs where you control the load.</li><li><strong>Examples:</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="important-notes" tabindex="-1">Important notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important notes&quot;">​</a></h2><ul><li><strong>Per-endpoint tracking</strong> — each endpoint is tracked independently. Calling one endpoint does not affect others.</li><li><strong>Error returned to LLM</strong> — the second call within the cooldown is rejected with a <code>rate_limit</code> error. The LLM receives the cooldown duration and can retry after waiting.</li><li><strong>No cleanup needed</strong> — the rate limiter tracks endpoints automatically and does not require maintenance.</li></ul>`,23)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
